import base64
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path
from urllib.request import urlopen


CONTRACT_B64 = ""
CONTENT_DIR = Path("/content")
CONTRACT_PATH = CONTENT_DIR / "clef-contract.json"
IMAGE_PATH = CONTENT_DIR / "candy-source.JPG"


def sha256(data):
    return hashlib.sha256(data).hexdigest().upper()


def event(name, **fields):
    print(
        json.dumps(
            {"timestamp_utc": datetime.now(timezone.utc).isoformat(), "event": name, **fields},
            ensure_ascii=False,
            sort_keys=True,
        ),
        flush=True,
    )


CONTENT_DIR.mkdir(parents=True, exist_ok=True)
contract_bytes = base64.b64decode(CONTRACT_B64)
contract = json.loads(contract_bytes.decode("utf-8"))
CONTRACT_PATH.write_text(contract_bytes.decode("utf-8"), encoding="utf-8")
if not CONTRACT_PATH.is_file() or CONTRACT_PATH.read_bytes() != contract_bytes:
    raise RuntimeError("Contract write verification failed.")
event(
    "contract_bootstrap_completed",
    path=str(CONTRACT_PATH),
    bytes=len(contract_bytes),
    sha256=sha256(contract_bytes),
    model=contract["target"]["model_id"],
    revision=contract["target"]["release_revision"],
)

image_case = next(case for case in contract["cases"] if case["modality"] == "image")
image_spec = image_case["input"]["image"]
event("image_bootstrap_download_started", source=image_spec["source"])
with urlopen(image_spec["source"], timeout=60) as response:
    image_bytes = response.read()
image_hash = sha256(image_bytes)
if image_hash != image_spec["source_sha256"]:
    raise ValueError(f"Image SHA-256 mismatch: expected {image_spec['source_sha256']}, got {image_hash}.")
IMAGE_PATH.write_bytes(image_bytes)
if not IMAGE_PATH.is_file() or sha256(IMAGE_PATH.read_bytes()) != image_hash:
    raise RuntimeError("Image write verification failed.")
event(
    "image_bootstrap_download_completed",
    path=str(IMAGE_PATH),
    bytes=len(image_bytes),
    sha256=image_hash,
)
